//! The common head of every shared block (docs/decisions/2026-11-20-abi-par-contrat.md §5): 32 bytes the writer
//! writes once, before it publishes the block's address, and a reader reads once when it binds. Written by hand (the
//! socle `gripforge:contracts@1`); the modules of each contract, generated by tools/contracts/gen.mjs, use it.
use core::fmt;
use core::sync::atomic::{AtomicU32, Ordering};

/// `GFT1`, little-endian: the first word of every block of a contract.
pub const MAGIC: u32 = 0x3154_4647;

/// The common head (§5). `fields`, `head_fields`, `stride`, `head_bytes` never change during the life of a block.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct TableHead {
    /// [`MAGIC`].
    pub magic: u32,
    /// FNV-1a 32 of the contract's name.
    pub contract: u32,
    /// The major of the contract the writer was built with.
    pub major: u16,
    /// The fields of a row the writer knows (the minor, in fact).
    pub fields: u16,
    /// The fields of the head the writer knows.
    pub head_fields: u16,
    /// 0 (reserved to the socle).
    pub flags: u16,
    /// The bytes of a row (a multiple of 8).
    pub stride: u32,
    /// 32 + the head of the contract, rounded up to 8: the rows begin there.
    pub head_bytes: u32,
    /// The rows reserved.
    pub slots: u32,
    /// The rows in service: the one word rewritten at each publication.
    pub count: u32,
}
const _: () = assert!(core::mem::size_of::<TableHead>() == 32);

/// A text in place: the address of its UTF-8 bytes in the writer's memory, its length, 4 bytes at 0 (16 bytes on every
/// target: never a pointer or a `usize`).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Str {
    /// The address of the bytes.
    pub addr: u64,
    /// The bytes.
    pub len: u32,
    /// 0.
    pub zero: u32,
}
const _: () = assert!(core::mem::size_of::<Str>() == 16);

/// What a reader of a build asks of the writer (generated per contract: `<contract>::SPEC`).
#[derive(Clone, Copy, Debug)]
pub struct Spec {
    /// The contract's name.
    pub name: &'static str,
    /// FNV-1a 32 of the name.
    pub id: u32,
    /// Its major.
    pub major: u16,
    /// The fields of a row this build knows.
    pub fields: u16,
    /// The fields of the head this build knows.
    pub head_fields: u16,
    /// The row fields a writer must know (up to the last with no default).
    pub required: u16,
    /// The head fields a writer must know.
    pub required_head: u16,
    /// The end (bytes) of the last required row field: the writer's stride holds at least that.
    pub required_end: u32,
    /// The end (bytes, from the block) of the last required head field.
    pub required_head_end: u32,
    /// The stride of this build (what its writer announces).
    pub stride: u32,
    /// The head bytes of this build.
    pub head_bytes: u32,
}

/// Why a block was refused at bind.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Why {
    /// Not a block of a contract (the magic found).
    Magic(u32),
    /// Another contract (the id found).
    Contract(u32),
    /// Another major (the one found).
    Major(u16),
    /// The writer knows fewer row fields (or words) than this build needs, with no default (the count found).
    Fields(u16),
    /// The writer knows fewer head fields than this build needs (the count found).
    HeadFields(u16),
    /// A stride that does not hold the fields read, or not a multiple of 8 (the one found).
    Stride(u32),
    /// Head bytes that do not hold the head read, or not a multiple of 8 (the ones found).
    HeadBytes(u32),
}

/// A refusal at bind, by name (`contract_refused: <contract> — <reason>`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Refused {
    /// The contract this build reads.
    pub contract: &'static str,
    /// Why.
    pub why: Why,
}

impl fmt::Display for Refused {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "contract_refused: {} — ", self.contract)?;
        match self.why {
            Why::Magic(m) => write!(f, "no TableHead (magic {m:#010x})"),
            Why::Contract(id) => write!(f, "the block is of another contract (id {id:#010x})"),
            Why::Major(m) => write!(f, "the writer has major {m}: rebuild the reader or the writer"),
            Why::Fields(n) => write!(f, "the writer knows {n} fields, this reader needs more with no default: rebuild the writer"),
            Why::HeadFields(n) => write!(f, "the writer knows {n} head fields, this reader needs more: rebuild the writer"),
            Why::Stride(s) => write!(f, "stride {s} does not hold the fields read"),
            Why::HeadBytes(b) => write!(f, "head bytes {b} do not hold the head read"),
        }
    }
}

/// FNV-1a 32 of a name (the contract id), usable in a `const`.
pub const fn fnv1a32(name: &str) -> u32 {
    let b = name.as_bytes();
    let mut h: u32 = 0x811c_9dc5;
    let mut i = 0;
    while i < b.len() {
        h = (h ^ b[i] as u32).wrapping_mul(0x0100_0193);
        i += 1;
    }
    h
}

impl TableHead {
    /// The head of a new block of `slots` rows written by a build of `spec` (count 0).
    pub const fn new(spec: &Spec, slots: u32) -> TableHead {
        TableHead {
            magic: MAGIC,
            contract: spec.id,
            major: spec.major,
            fields: spec.fields,
            head_fields: spec.head_fields,
            flags: 0,
            stride: spec.stride,
            head_bytes: spec.head_bytes,
            slots,
            count: 0,
        }
    }

    /// The head as its 8 little-endian words, in order: for a writer that stores a block word by word where it cannot
    /// lend a pointer (a block of the zone written through the zone's own store, `kithost.scene` records).
    pub const fn to_words(&self) -> [u32; 8] {
        [
            self.magic,
            self.contract,
            self.major as u32 | (self.fields as u32) << 16,
            self.head_fields as u32 | (self.flags as u32) << 16,
            self.stride,
            self.head_bytes,
            self.slots,
            self.count,
        ]
    }

    /// The head from its 8 words (see [`TableHead::to_words`]): for a reader that reads a block word by word across two
    /// memories (an isolated kit module reads the zone through calls), once, at bind.
    pub const fn from_words(w: [u32; 8]) -> TableHead {
        TableHead {
            magic: w[0],
            contract: w[1],
            major: w[2] as u16,
            fields: (w[2] >> 16) as u16,
            head_fields: w[3] as u16,
            flags: (w[3] >> 16) as u16,
            stride: w[4],
            head_bytes: w[5],
            slots: w[6],
            count: w[7],
        }
    }

    /// Reads the head of a block (once, at bind).
    ///
    /// # Safety
    /// `block` aligned on 8, holding at least 32 bytes.
    pub unsafe fn read(block: *const u8) -> TableHead {
        core::ptr::read(block as *const TableHead)
    }

    /// Writes the head of a new block (before its address is published).
    ///
    /// # Safety
    /// As [`TableHead::read`], and nobody reads the block yet.
    pub unsafe fn write(block: *mut u8, spec: &Spec, slots: u32) {
        core::ptr::write(block as *mut TableHead, TableHead::new(spec, slots));
    }

    /// The rows in service (Acquire).
    ///
    /// # Safety
    /// As [`TableHead::read`].
    #[inline]
    pub unsafe fn count(block: *const u8) -> u32 {
        (*(block.add(28) as *const AtomicU32)).load(Ordering::Acquire)
    }

    /// Publishes `count` rows (Release).
    ///
    /// # Safety
    /// As [`TableHead::read`]; the writer alone calls it.
    #[inline]
    pub unsafe fn set_count(block: *mut u8, count: u32) {
        (*(block.add(28) as *const AtomicU32)).store(count, Ordering::Release);
    }

    /// Whether a reader of `spec` may read this block, at its stride: the same contract and major, the fields with no
    /// default known by the writer, a stride and head that hold them.
    pub fn check(&self, spec: &Spec) -> Result<(), Refused> {
        let no = |why| {
            Err(Refused {
                contract: spec.name,
                why,
            })
        };
        if self.magic != MAGIC {
            return no(Why::Magic(self.magic));
        }
        if self.contract != spec.id {
            return no(Why::Contract(self.contract));
        }
        if self.major != spec.major {
            return no(Why::Major(self.major));
        }
        if self.fields < spec.required {
            return no(Why::Fields(self.fields));
        }
        if self.head_fields < spec.required_head {
            return no(Why::HeadFields(self.head_fields));
        }
        if !self.stride.is_multiple_of(8) || self.stride < spec.required_end {
            return no(Why::Stride(self.stride));
        }
        if !self.head_bytes.is_multiple_of(8) || self.head_bytes < spec.required_head_end.max(32) {
            return no(Why::HeadBytes(self.head_bytes));
        }
        Ok(())
    }
}
